local DistillationApparatusMaker = {}
local PRODUCTS = {
    simple_glass_distillation = { name = "Preprosta steklena destilatorna naprava", glassCost = 3, clayCost = 1, time = 5, cost = 120, science = 25, happiness = 1, description = "Preprosta steklena destilatorna naprava za destilacijo." },
    brass_framed_distillation = { name = "Medeninasto okvirjena destilatorna naprava", glassCost = 3, brassCost = 2, clayCost = 1, time = 8, cost = 320, science = 40, happiness = 2, prestige = 2, description = "Medeninasto okvirjena destilatorna naprava za trgovce." },
    silver_jointed_distillation = { name = "Srebrnospojna destilatorna naprava", glassCost = 4, silverCost = 1, brassCost = 2, clayCost = 1, time = 12, cost = 760, science = 55, happiness = 2, prestige = 6, description = "Srebrnospojna destilatorna naprava za plemiče." },
    gold_trimmed_distillation = { name = "Zlatookrasna destilatorna naprava", glassCost = 4, goldCost = 1, silverCost = 1, brassCost = 2, clayCost = 1, time = 16, cost = 1800, science = 70, happiness = 3, prestige = 14, description = "Zlatookrasna destilatorna naprava za visoke plemiče." },
    jewel_valve_distillation = { name = "Draguljnoventilna destilatorna naprava", glassCost = 5, goldCost = 1, silverCost = 1, brassCost = 2, clayCost = 1, jewelCost = 1, time = 20, cost = 3900, science = 85, happiness = 5, prestige = 27, description = "Destilatorna naprava z draguljnim ventilom za visoko plemstvo." },
    royal_grand_distillation = { name = "Kraljevski veliki destilatorna naprava", glassCost = 7, goldCost = 2, silverCost = 2, brassCost = 2, clayCost = 1, jewelCost = 2, pearlCost = 2, time = 27, cost = 8500, science = 95, happiness = 12, prestige = 58, description = "Velika kraljevska destilatorna naprava z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    distillation_workshop = { name = "Destilatorna delavnica", cost = { gold = 300, wood = 120, stone = 160, glass = 8, clay = 6 }, upkeep = 7, qualityBonus = 5 },
    alchemy_loft = { name = "Alkemična podstrešje", cost = { gold = 1100, wood = 280, stone = 280, silver = 6, brass = 6 }, upkeep = 26, qualityBonus = 18 },
    master_distiller_atelier = { name = "Mojstrski destilatorski atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_alchemy_palace = { name = "Kraljevska alkemična palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
DistillationApparatusMaker.glassStock = 18; DistillationApparatusMaker.clayStock = 10; DistillationApparatusMaker.brassStock = 12; DistillationApparatusMaker.silverStock = 6; DistillationApparatusMaker.goldStock = 6; DistillationApparatusMaker.jewelStock = 4; DistillationApparatusMaker.pearlStock = 4
DistillationApparatusMaker.productStock = {}; DistillationApparatusMaker.buildings = {}; DistillationApparatusMaker.maker = nil; DistillationApparatusMaker.activeMaking = {}; DistillationApparatusMaker.totalProducts = 0; DistillationApparatusMaker.dayTimer = 0
function DistillationApparatusMaker.init() DistillationApparatusMaker.glassStock=18; DistillationApparatusMaker.clayStock=10; DistillationApparatusMaker.brassStock=12; DistillationApparatusMaker.silverStock=6; DistillationApparatusMaker.goldStock=6; DistillationApparatusMaker.jewelStock=4; DistillationApparatusMaker.pearlStock=4; DistillationApparatusMaker.productStock={}; DistillationApparatusMaker.buildings={}; DistillationApparatusMaker.maker=nil; DistillationApparatusMaker.activeMaking={}; DistillationApparatusMaker.totalProducts=0; DistillationApparatusMaker.dayTimer=0; print("[DistillationApparatusMaker] Royal Distillation Apparatus Maker System initialized (6 products, 4 buildings)") end
function DistillationApparatusMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; DistillationApparatusMaker.maker={name=n or ("Destilator "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Destilator najet: %s (spretnost: %d)",DistillationApparatusMaker.maker.name,s),"success") end; return true end
function DistillationApparatusMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function DistillationApparatusMaker.build(id) local ok,e=DistillationApparatusMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(DistillationApparatusMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function DistillationApparatusMaker.getQualityBonus() local b=0; for _,bd in ipairs(DistillationApparatusMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function DistillationApparatusMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and DistillationApparatusMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.clayCost and DistillationApparatusMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.brassCost and DistillationApparatusMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and DistillationApparatusMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and DistillationApparatusMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and DistillationApparatusMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and DistillationApparatusMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #DistillationApparatusMaker.buildings==0 then return false,"Potrebna destilatorna delavnica" end; if not DistillationApparatusMaker.maker then return false,"Potreben destilator" end; return true end
function DistillationApparatusMaker.make(pt,qty) qty=qty or 1; local ok,e=DistillationApparatusMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then DistillationApparatusMaker.glassStock=DistillationApparatusMaker.glassStock-d.glassCost*qty end; if d.clayCost then DistillationApparatusMaker.clayStock=DistillationApparatusMaker.clayStock-d.clayCost*qty end; if d.brassCost then DistillationApparatusMaker.brassStock=DistillationApparatusMaker.brassStock-d.brassCost*qty end; if d.silverCost then DistillationApparatusMaker.silverStock=DistillationApparatusMaker.silverStock-d.silverCost*qty end; if d.goldCost then DistillationApparatusMaker.goldStock=DistillationApparatusMaker.goldStock-d.goldCost*qty end; if d.jewelCost then DistillationApparatusMaker.jewelStock=DistillationApparatusMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then DistillationApparatusMaker.pearlStock=DistillationApparatusMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if DistillationApparatusMaker.maker then t=math.max(1,t-math.floor(DistillationApparatusMaker.maker.skill/12)) end; table.insert(DistillationApparatusMaker.activeMaking,{id="distillationapp_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function DistillationApparatusMaker.completeMaking(m) local q=1.0+(DistillationApparatusMaker.getQualityBonus()/100); if DistillationApparatusMaker.maker then q=q+(DistillationApparatusMaker.maker.skill/140) end; q=math.min(2.5,q); DistillationApparatusMaker.productStock[m.productType]=(DistillationApparatusMaker.productStock[m.productType] or 0)+m.quantity; DistillationApparatusMaker.totalProducts=DistillationApparatusMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if DistillationApparatusMaker.maker then DistillationApparatusMaker.maker.itemsMade=DistillationApparatusMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then DistillationApparatusMaker.maker.skill=math.min(100,DistillationApparatusMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Destilatorna naprava izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"distillationapp.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function DistillationApparatusMaker.update(dt) if not _G.state then return end; DistillationApparatusMaker.dayTimer=DistillationApparatusMaker.dayTimer+dt; if DistillationApparatusMaker.dayTimer>=30 then DistillationApparatusMaker.dayTimer=0; for i=#DistillationApparatusMaker.activeMaking,1,-1 do local m=DistillationApparatusMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then DistillationApparatusMaker.completeMaking(m); table.remove(DistillationApparatusMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(DistillationApparatusMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if DistillationApparatusMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function DistillationApparatusMaker.getStats() return {glassStock=DistillationApparatusMaker.glassStock,clayStock=DistillationApparatusMaker.clayStock,brassStock=DistillationApparatusMaker.brassStock,silverStock=DistillationApparatusMaker.silverStock,goldStock=DistillationApparatusMaker.goldStock,jewelStock=DistillationApparatusMaker.jewelStock,pearlStock=DistillationApparatusMaker.pearlStock,productStock=DistillationApparatusMaker.productStock,numBuildings=#DistillationApparatusMaker.buildings,hasMaker=DistillationApparatusMaker.maker~=nil,makerName=DistillationApparatusMaker.maker and DistillationApparatusMaker.maker.name or "—",makerSkill=DistillationApparatusMaker.maker and DistillationApparatusMaker.maker.skill or 0,activeMaking=#DistillationApparatusMaker.activeMaking,totalProducts=DistillationApparatusMaker.totalProducts} end
return DistillationApparatusMaker
